-- ============================================================
-- Nathrezim Pact (200403) -- demoted to a hidden driver aura
-- ============================================================
-- The damage reduction and spell crit move to the visible stacking buff
-- 200507; 200403 keeps only its Effect3 PERIODIC_DUMMY heartbeat, which is
-- what resyncs the stack count with the Soul Shards in the bags.
--
-- Attributes 464 -> 400 drops SPELL_ATTR0_PASSIVE (0x40).  Aura::CanBeSaved
-- (SpellAuras.cpp:1057) refuses to persist passive auras, so the pact used
-- to die at logout and cost another demon plus a 3 minute cooldown to get
-- back.  SPELL_ATTR0_DO_NOT_DISPLAY (0x80) is kept, so it stays out of the
-- buff bar.
--
-- Clearing PASSIVE would also make Player::RemoveAllAurasOnDeath strip it,
-- so SPELL_ATTR3_ALLOW_AURA_WHILE_DEAD (0x100000) is added on top of the
-- existing AttributesEx3 (524288 + 1048576 = 1572864).  The pact is a bargain
-- with the Nathrezim, not a buff -- dying does not end it.

UPDATE `alonecraft_spell_dbc` SET
    `SpellName0` = 'Nathrezim Pact',
    `Attributes` = 400,
    `AttributesEx3` = 1572864,
    `Effect1` = 0, `EffectApplyAuraName1` = 0, `EffectMiscValue1` = 0,
    `EffectBasePoints1` = 0, `EffectDieSides1` = 0, `EffectImplicitTargetA1` = 0,
    `Effect2` = 0, `EffectApplyAuraName2` = 0, `EffectMiscValue2` = 0,
    `EffectBasePoints2` = 0, `EffectDieSides2` = 0, `EffectImplicitTargetA2` = 0,
    `SpellDescription0` = 'Your demon serves a new master in the Twisting Nether. The Nathrezim grant you their foresight while you carry Soul Shards.'
WHERE `ID` = 200403;


-- ============================================================
-- Infernal Bargain buff (200405) -- make it visible
-- ============================================================
-- Attributes 400 -> 272 clears SPELL_ATTR0_DO_NOT_DISPLAY (0x80).  The buff
-- was being applied and its stacks were scaling correctly all along; the
-- client was simply told to hide it, so the channel appeared to do nothing.
-- Same fix woa_2026_08_03_11.sql applied to 47220.
--
-- 200401/200404 are dropped by woa_2026_08_03_12.sql; listing them costs
-- nothing and keeps this file correct if that rank collapse is ever reverted.

UPDATE `alonecraft_spell_dbc` SET `Attributes` = 272 WHERE `ID` IN (200401, 200404, 200405);


-- ============================================================
-- Sacrifice the Weak (47220) -- tooltip now describes the stacks
-- ============================================================

UPDATE `alonecraft_spell_dbc` SET
    `SpellDescription0` = 'Sacrifice your demon to a new master in the Twisting Nether. In return they grant you Nathrezim Foresight, reducing damage taken and increasing the critical effect chance of your spells by 1% for each Soul Shard you carry, up to 32.'
WHERE `ID` = 47220;


-- ============================================================
-- Script registrations
-- ============================================================
-- Unchanged, re-emitted so this file is self-contained.  Note 200403 keeps
-- the `spell_warl_nathrezim_foresight` script name even though the spell is
-- now the Pact: the loader name is the contract with the DB, and renaming it
-- would orphan the row for no gain.

DELETE FROM `spell_script_names` WHERE `ScriptName` IN ('spell_warl_sacrifice_the_weak', 'spell_warl_nathrezim_foresight');
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(47220, 'spell_warl_sacrifice_the_weak'),
(200403, 'spell_warl_nathrezim_foresight');
